import{_ as t,o as a,c as i,a5 as r}from"./chunks/framework.BvXk9IVy.js";const _=JSON.parse('{"title":"弈辰小传","description":"","frontmatter":{"title":"弈辰小传"},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1791895356000}'),l={name:"about.md"};function o(p,e,n,s,d,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="弈辰小传" tabindex="-1">弈辰小传</h1><blockquote><p>弈者，局中人也；辰者，时也。落子无悔，只争朝夕。</p></blockquote><div class="about-avatar"><p><img src="https://cdn.jsdelivr.net/gh/yichen0808/Blog-images@main/images/avatar.jpg" alt="弈辰的头像"></p></div><h2 id="关于这个名字" tabindex="-1">关于这个名字</h2><p>取「弈」是因为喜欢下棋，尤其喜欢那种一步落下就再也收不回来的感觉。取「辰」是因为时间——写下来的东西，多半是为了给某一段时间留个记号。</p><p>合起来没什么深意，就是希望自己在有限的时辰里，多下几盘认真的棋。</p><h2 id="关于这间书斋" tabindex="-1">关于这间书斋</h2><p>「小筑」是简陋居所的意思。这里也一样：没有评论区，没有推荐算法，没有阅读量统计。只有我写下的东西，和偶尔路过的你。</p><p>技术栈是 VitePress + Vue 3 + TypeScript，主题是自己改的。配色取自宣纸白、竹青、朱砂和古铜金，字体用了霞鹜文楷——都是些让人看着安静下来的东西。</p><p>想看看这间书斋是怎么搭起来的，可以翻 <a href="/Blog-pages/diary/">随心记</a>。</p><h2 id="在做的事" tabindex="-1">在做的事</h2><ul><li>写 Java 和 Vue，最近在折腾前端构建工具链</li><li>读小说，偏好历史和武侠，也看科幻</li><li>拍照，水平一般，但很享受按快门之前那几秒</li><li>试图把「坚持写博客」这件事做得比上次久一点</li></ul><h2 id="找到我" tabindex="-1">找到我</h2><p>如果哪篇笔记帮到了你，或者你只是想聊两句：</p><ul><li>GitHub：<a href="https://github.com/yichen0808" target="_blank" rel="noreferrer">github.com/yichen0808</a></li><li>邮箱：<a href="mailto:3420905329@qq.com" target="_blank" rel="noreferrer">3420905329@qq.com</a></li></ul><p>回信可能不快，但都会回。</p>',16)])])}const u=t(l,[["render",o]]);export{_ as __pageData,u as default};
